def allocate(pool, prev_offer, prev_contrib, t, mem, cap, growth):
    p = prev_offer.shape[1]
    if t == 1:
        mem['rate'] = np.full((pool.shape[0], p), 0.5)
    else:
        frac = np.where(prev_offer > 0.5, prev_contrib / np.maximum(prev_offer, 1e-6), mem['rate'])
        mem['rate'] = 0.7 * mem['rate'] + 0.3 * frac
    # keep enough in reserve to sustain growth; offer only a fraction of pool, biased to reliable agents
    budget = 0.5 * pool[:, None]
    weight = 0.2 + mem['rate']
    share = weight / weight.sum(axis=1, keepdims=True)
    offer = budget * share
    return np.maximum(offer, np.minimum(1.0, pool[:, None] / p))

