        mem['trust'] = 0.8 * mem['trust'] + 0.2 * frac
    trust = mem['trust']
    share = (0.2 + trust) / (0.2 + trust).sum(axis=1, keepdims=True)
    budget = np.minimum(pool, 0.5 * cap) [:, None] * share
    return np.maximum(budget, np.minimum(1.0, pool[:, None] / p))

def allocate(pool, prev_offer, prev_contrib, t, mem, cap, growth):
    p = prev_offer.shape[1]
    if "rate" not in mem:
        mem["rate"] = np.full((pool.shape[0], p), 0.5)
    if t > 1:
        obs = np.where(prev_offer > 0, prev_contrib / np.maximum(prev_offer, 1e-9), mem["rate"])
        mem["rate"] = 0.8 * mem["rate"] + 0.2 * obs
    rate = mem["rate"]
    weight = 0.2 + rate
    share = weight / weight.sum(axis=1, keepdims=True)
    budget = np.minimum(pool, 0.5 * pool + 0.3 * rate.mean(axis=1) * pool)
    offer = np.maximum(budget[:, None] * share, 1.0)
    return np.minimum(offer, pool[:, None] * share / share.sum(axis=1, keepdims=True))

def allocate(pool, prev_offer, prev_contrib, t, mem, cap, growth):
    """Minimal scarcity-sharpened rule distilled from the best blind share-interface program.
    Weights: last round's returns plus a constant, raised to an exponent that falls from 1.75
    (empty pool) to 0.85 (full pool); the interface offers the whole pool in proportion to them."""
    fullness = np.clip(pool / cap, 0.0, 1.0)[:, None]
    return (prev_contrib + 10.0 / 3.0) ** (1.75 - 0.9 * fullness)
